  <script>
    function toggleMenu() {
      var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu');
      if (dropdown) dropdown.classList.toggle('open');
    }
    document.addEventListener('click', function(e) {
      var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu');
      if (!e.target.closest('.viz-menu') && dropdown) dropdown.classList.remove('open');
    });
    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape') {
        var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu');
        if (dropdown) dropdown.classList.remove('open');
      }
    });

    var savedTheme = localStorage.getItem('viz-theme');
    var currentTheme = savedTheme || 'dark';
    function applyTheme(t) {
      document.documentElement.className = 'theme-' + t;
      document.getElementById('themeIcon').textContent = t === 'dark' ? '🌙' : '☀️';
      document.getElementById('themeLabel').textContent = t === 'dark' ? 'Dark' : 'Light';
      localStorage.setItem('viz-theme', t);
      currentTheme = t;
      if (typeof onThemeChange === 'function') onThemeChange();
    }
    function cycleTheme() { applyTheme(currentTheme === 'dark' ? 'light' : 'dark'); }
    applyTheme(currentTheme);

    document.querySelectorAll('[data-reveal]').forEach(function(el) { el.classList.add('reveal'); });
    var revealObserver = new IntersectionObserver(function(entries) {
      entries.forEach(function(e) { if (e.isIntersecting) { e.target.classList.add('visible'); revealObserver.unobserve(e.target); } });
    }, { threshold: 0.15 });
    document.querySelectorAll('.reveal').forEach(function(el) { revealObserver.observe(el); });

    function animateCounters() {
      document.querySelectorAll('[data-count]').forEach(function(el) {
        if (el.dataset.counted) return;
        el.dataset.counted = '1';
        var target = parseFloat(el.dataset.count);
        var suffix = el.dataset.suffix || '';
        var prefix = el.dataset.prefix || '';
        var decimals = String(target).indexOf('.') >= 0 ? 2 : 0;
        var start = performance.now();
        function tick(now) {
          var progress = Math.min((now - start) / 900, 1);
          var eased = 1 - Math.pow(1 - progress, 3);
          var value = target * eased;
          el.textContent = prefix + value.toFixed(decimals) + suffix;
          if (progress < 1) requestAnimationFrame(tick); else el.textContent = prefix + target.toFixed(decimals).replace(/\.00$/, '') + suffix;
        }
        requestAnimationFrame(tick);
      });
    }
    animateCounters();

    function downloadImage() {
      var node = document.getElementById('main-content');
      htmlToImage.toPng(node, { pixelRatio: 1, backgroundColor: '#07101f' })
        .then(function(dataUrl) {
          var link = document.createElement('a');
          link.download = 'bot-mitigation-poster.png';
          link.href = dataUrl;
          link.click();
        })
        .catch(function(error) { console.error('PNG export failed:', error); });
    }

    var ChartManager = {
      charts: new Map(),
      safeInit: function(canvasId, config) {
        if (typeof Chart === 'undefined') { console.error('Chart.js library not loaded - check CDN inclusion'); return null; }
        try {
          if (this.charts.has(canvasId)) { this.charts.get(canvasId).destroy(); this.charts.delete(canvasId); }
          var ctx = document.getElementById(canvasId);
          if (!ctx) { console.error('Canvas element not found: ' + canvasId); return null; }
          if (ctx.chart) { ctx.chart.destroy(); delete ctx.chart; }
          ctx.setAttribute('role', 'img');
          if (!ctx.getAttribute('aria-label')) ctx.setAttribute('aria-label', 'Chart visualization');
          var chart = new Chart(ctx.getContext('2d'), config);
          ctx.chart = chart;
          this.charts.set(canvasId, chart);
          return chart;
        } catch (error) { console.error('Chart creation failed for ' + canvasId + ':', error); return null; }
      },
      destroyAll: function() { this.charts.forEach(function(chart) { chart.destroy(); }); this.charts.clear(); }
    };
    var chartsBuilt = false;
    function buildCharts() {
      if (chartsBuilt || typeof Chart === 'undefined') { if (typeof Chart === 'undefined') console.error('Chart.js not loaded'); return; }
      var textColor = '#f4f9ff';
      var muted = '#a8bdd5';
      var gridColor = 'rgba(255,255,255,0.08)';
      ChartManager.safeInit('trafficChart', {
        type: 'doughnut',
        data: { labels: ['Bot traffic', 'Human traffic'], datasets: [{ data: [47, 53], backgroundColor: ['#32d6ff', 'rgba(255,255,255,0.13)'], borderColor: ['#32d6ff', 'rgba(255,255,255,0.22)'], borderWidth: 2 }] },
        options: { responsive: true, maintainAspectRatio: false, cutout: '66%', plugins: { tooltip: { enabled: true }, legend: { position: 'bottom', labels: { color: muted, font: { family: 'Inter', size: 19 } } } } }
      });
      ChartManager.safeInit('outcomeChart', {
        type: 'bar',
        data: { labels: ['Scraping attempts', 'Origin CPU', 'Complaints'], datasets: [{ label: 'Before mitigation', data: [100, 78, 100], backgroundColor: 'rgba(251,113,133,0.62)', borderColor: '#fb7185', borderWidth: 1 }, { label: 'After mitigation', data: [15, 42, 28], backgroundColor: 'rgba(22,242,179,0.68)', borderColor: '#16f2b3', borderWidth: 1 }] },
        options: { responsive: true, maintainAspectRatio: false, plugins: { tooltip: { enabled: true }, legend: { labels: { color: textColor, font: { family: 'Inter', size: 17 } } } }, scales: { x: { ticks: { color: muted, font: { family: 'Inter', size: 15 } }, grid: { color: gridColor } }, y: { beginAtZero: true, ticks: { color: muted, font: { family: 'Inter', size: 15 }, callback: function(value) { return value + '%'; } }, grid: { color: gridColor } } } }
      });
      chartsBuilt = true;
    }
    function onThemeChange() { ChartManager.destroyAll(); chartsBuilt = false; buildCharts(); }
    buildCharts();
  </script>
</body>
</html>
