const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch({ headless: true, args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 2400, height: 3394 }, deviceScaleFactor: 1 });
  const errors = [];
  page.on('console', msg => { if (msg.type() === 'error') errors.push(msg.text()); });
  page.on('pageerror', err => errors.push(err.message));
  await page.goto('file:///app/output/poster.html', { waitUntil: 'networkidle' });
  await page.evaluate(() => document.documentElement.className = 'theme-dark');
  await page.waitForTimeout(500);
  const poster = await page.$('#main-content');
  await poster.screenshot({ path: '/app/output/final_poster.png' });
  await browser.close();
  if (errors.length) {
    console.error(errors.join('\n'));
    process.exitCode = 1;
  }
})();
